'use strict';
// 설정: 목표 매출 / 최대 판매 건수 / 시작 재고
const CONFIG = Object.freeze({target:24000,maxOrders:6,coffee:9,milk:5});
const MENU = Object.freeze({americano:{name:'아메리카노',coffee:1,milk:0,price:3000},latte:{name:'카페라떼',coffee:1,milk:1,price:4500},double:{name:'더블 라떼',coffee:2,milk:1,price:6000}});
// 3명씩 대기합니다. 판매한 자리에 다음 손님이 나타납니다.
const LINE=['double','latte','americano','double','latte','double','double','latte','americano','double','latte','double'];
const $=id=>document.getElementById(id);
const money=n=>n.toLocaleString('ko-KR')+'원';
let state,audioContext,toastTimer,transitionTimer,pourTimer;
const PORTRAITS=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
function sound(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audioContext||=new A();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});const t=audioContext.currentTime;for(const [offset,freq] of [[0,570],[.075,790]]){const osc=audioContext.createOscillator(),g=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,t+offset);g.gain.setValueAtTime(.0001,t+offset);g.gain.exponentialRampToValueAtTime(.095,t+offset+.008);g.gain.exponentialRampToValueAtTime(.0001,t+offset+.12);osc.connect(g).connect(audioContext.destination);osc.start(t+offset);osc.stop(t+offset+.13)}}catch(e){}}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1800)}
function createGuest(){if(state.next>=LINE.length)return null;const id=state.next++;return{id,type:LINE[id],portrait:PORTRAITS[id%PORTRAITS.length]}}
function current(){return state.guests.find(g=>g&&g.id===state.selectedId)}
function refund(){state.coffee+=state.cup.coffee;state.milk+=state.cup.milk;state.cup={coffee:0,milk:0}}
function startGame(){clearTimeout(transitionTimer);clearTimeout(pourTimer);state={coffee:CONFIG.coffee,milk:CONFIG.milk,sales:0,served:0,selectedId:null,cup:{coffee:0,milk:0},guests:[],next:0,busy:false,finished:false};for(let i=0;i<3;i++)state.guests.push(createGuest());$('resultModal').classList.add('hidden');$('targetValue').textContent=money(CONFIG.target);render()}
function selectGuest(id){if(state.busy||state.finished)return;if(state.selectedId!==id){refund();state.selectedId=id;sound();render()}}
function renderGuests(enterId=null){const root=$('customers');root.replaceChildren();for(let slot=0;slot<3;slot++){const guest=state.guests[slot];if(!guest){const empty=document.createElement('div');empty.className='empty-seat';empty.textContent='빈 자리';root.append(empty);continue}const drink=MENU[guest.type],btn=document.createElement('button');btn.type='button';btn.className='customer'+(guest.id===state.selectedId?' active':'')+(guest.id===enterId?' enter':'');btn.disabled=state.busy||state.finished;btn.dataset.guestId=guest.id;btn.innerHTML=`<span class="portrait" style="background-image:url('${guest.portrait}')"></span><span class="order-bubble">☕ ${drink.name}</span><span class="customer-info"><span><strong>${slot+1}번 손님</strong><small>🫘 ${drink.coffee} · 🥛 ${drink.milk}</small></span><span class="price">${money(drink.price)}</span></span>`;btn.setAttribute('aria-label',`${slot+1}번 손님, ${drink.name}, 커피 ${drink.coffee}개 우유 ${drink.milk}개`);btn.addEventListener('click',()=>selectGuest(guest.id));root.append(btn)}}
function render(){const guest=current(),drink=guest?MENU[guest.type]:null;const total=state.cup.coffee+state.cup.milk;const matched=!!drink&&state.cup.coffee===drink.coffee&&state.cup.milk===drink.milk;$('salesValue').textContent=money(state.sales);$('servedValue').textContent=`${state.served} / ${CONFIG.maxOrders}`;$('coffeeValue').textContent=state.coffee+'개';$('milkValue').textContent=state.milk+'개';$('progressFill').style.width=Math.min(100,state.sales/CONFIG.target*100)+'%';renderGuests();$('selectedLabel').textContent=drink?'선택 주문: '+drink.name:'손님을 선택해 주세요';$('recipeText').textContent=drink?`🫘 커피 ${drink.coffee}개 · 🥛 우유 ${drink.milk}개`:'손님을 먼저 선택하세요';$('cupCount').textContent=`🫘 커피 ${state.cup.coffee}개 · 🥛 우유 ${state.cup.milk}개`;
const visual=$('drinkVisual');visual.className='drink-visual'+(matched?' finished '+(guest.type==='americano'?'americano':'latte'):'');$('drinkLayer').style.height=matched?'88%':Math.min(85,state.cup.coffee*26+state.cup.milk*19)+'%';$('drinkLayer').style.background=state.cup.milk?'linear-gradient(#d9b189,#b77b52,#e9cda8)':'linear-gradient(#986344,#5b321f)';$('drinkCaption').textContent=matched?`✨ ${drink.name} 완성!`:total?'제조 중':'빈 컵';$('addCoffee').disabled=!guest||state.finished||state.busy||state.coffee<=0;$('addMilk').disabled=!guest||state.finished||state.busy||state.milk<=0;$('resetCup').disabled=!total||state.finished||state.busy;$('serveBtn').disabled=!matched||state.finished||state.busy;$('hint').textContent=matched?'음료가 완성되었습니다! 「음료 전달하기」를 눌러 주세요.':drink?`필요한 재료: 커피 ${drink.coffee}개, 우유 ${drink.milk}개. 잘못 넣었다면 재료 되돌리기를 눌러 주세요.`:'손님을 선택하면 레시피가 표시됩니다.'}
function addIngredient(kind){if(state.busy||state.finished||!current()||state[kind]<=0)return;state[kind]--;state.cup[kind]++;sound();render();const pour=$('pour');pour.className='pour-effect';void pour.offsetWidth;pour.className='pour-effect '+kind+' play';clearTimeout(pourTimer);pourTimer=setTimeout(()=>{pour.className='pour-effect'},530)}
function resetCup(){if(state.busy||state.finished)return;refund();sound();render();toast('재료를 재고로 되돌렸습니다.')}
function serve(){const guest=current();if(!guest||state.busy||state.finished)return;const drink=MENU[guest.type];if(state.cup.coffee!==drink.coffee||state.cup.milk!==drink.milk)return;sound();state.busy=true;state.sales+=drink.price;state.served++;state.cup={coffee:0,milk:0};state.selectedId=null;render();const leaving=document.querySelector(`[data-guest-id="${guest.id}"]`);if(leaving)leaving.classList.add('leave');toast(`${drink.name} 판매 완료! +${money(drink.price)}`);transitionTimer=setTimeout(()=>{const slot=state.guests.findIndex(g=>g&&g.id===guest.id);if(slot>=0)state.guests[slot]=state.served>=CONFIG.maxOrders?null:createGuest();state.busy=false;renderGuests(state.guests[slot]?.id);render();if(slot>=0&&state.guests[slot]){const arriving=document.querySelector(`[data-guest-id="${state.guests[slot].id}"]`);if(arriving)arriving.classList.add('enter')}checkResult()},500)}
function checkResult(){if(state.sales>=CONFIG.target)return finish(true);if(state.served>=CONFIG.maxOrders)return finish(false);const remaining=state.guests.filter(Boolean);if(!remaining.length||remaining.every(g=>MENU[g.type].coffee>state.coffee||MENU[g.type].milk>state.milk))finish(false)}
function finish(won){state.finished=true;render();$('resultEmoji').textContent=won?'🎉':'🌙';$('resultTitle').textContent=won?'영업 성공!':'영업 종료';$('resultDescription').textContent=won?'목표 매출을 달성했습니다!':'목표 매출에 도달하지 못했습니다. 주문 순서를 바꿔 다시 도전해 보세요.';$('finalSales').textContent=money(state.sales);$('resultModal').classList.remove('hidden');$('playAgainBtn').focus()}
$('addCoffee').addEventListener('click',()=>addIngredient('coffee'));$('addMilk').addEventListener('click',()=>addIngredient('milk'));$('resetCup').addEventListener('click',resetCup);$('serveBtn').addEventListener('click',serve);$('restartBtn').addEventListener('click',()=>{sound();startGame()});$('playAgainBtn').addEventListener('click',()=>{sound();startGame()});startGame();
